/bin/zsh -lc "python3 - <<'PY'
from sgf_parsing import parse, SgfTree

expected = SgfTree(
    {\"FF\": [\"4\"], \"C\": [\"root\"], \"SZ\": [\"19\"]},
    [SgfTree({\"B\": [\"aa\"]}, [SgfTree({\"W\": [\"ab\"]})])],
)
assert parse(\"(;FF[4]C[root]SZ[19];B[aa];W[ab])\") == expected

branches = parse(\"(;FF[4](;B[aa];W[ab])(;B[dd];W[ee]))\")
assert len(branches.children) == 2
assert [branch.properties for branch in branches.children] == [{\"B\": [\"aa\"]}, {\"B\": [\"dd\"]}]
assert parse(\"(;AB[aa][ab][ba])\").properties == {\"AB\": [\"aa\", \"ab\", \"ba\"]}
assert parse(\"(;C[a\\\\]b\\\\\\\\c])\").properties == {\"C\": [\"a]b\\\\c\"]}
assert parse(\"(;C[a\\tb\\nc])\").properties == {\"C\": [\"a b\\nc\"]}
assert parse(\"(;C[a\\\\\\nb])\").properties == {\"C\": [\"ab\"]}
print(\"sanity checks passed\")
PY"

